<style>.modal .box>h2{text-align:center}.modal .box>.hint{display:none}.welfare-option-actions{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.welfare-add-option,.welfare-no-option{margin-top:8px;padding:8px 12px;border:0;border-radius:8px;color:#fff;font-weight:800;cursor:pointer}.welfare-add-option{background:#64748b}.welfare-no-option{background:#0a8a85}.welfare-no-option.active{background:#d6f5ec;color:#08756f;box-shadow:inset 0 0 0 2px #69cbbd}#toast{position:fixed;left:auto;bottom:32px;right:32px;z-index:100001;font-size:1.5rem;padding:21px 33px;border-radius:18px;background:linear-gradient(135deg,var(--blue),var(--blue2));color:#fff;font-weight:800;box-shadow:0 6px 24px rgba(13,95,163,.4);border:2px solid rgba(255,255,255,.25);display:none;max-width:480px;font-family:'Plus Jakarta Sans',sans-serif;line-height:1.2;transform:none!important}#toast.error{background:linear-gradient(135deg,var(--danger),#b02030)}#toast.show{display:block;animation:welfareToastPop .22s ease}@keyframes welfareToastPop{from{transform:translateY(12px) scale(.92);opacity:0}to{transform:translateY(0) scale(1);opacity:1}}</style>
<style>#welfareConfirmOverlay{position:fixed;inset:0;background:rgba(0,0,0,.35);z-index:100002;display:none}#welfareConfirmOverlay.show{display:block}.welfare-confirm{position:fixed;top:50vh;left:50vw;transform:translate(-50%,-50%);z-index:100003;background:var(--surf);border:2px solid var(--bd2);border-radius:var(--r);padding:2rem 2.4rem;max-width:460px;width:90vw;box-shadow:0 12px 40px rgba(0,0,0,.35);text-align:center;display:none}.welfare-confirm.show{display:block;animation:welfareConfirmPop .22s ease}.welfare-confirm .confirm-close{position:absolute;top:12px;right:18px;width:32px;height:32px;border:0;border-radius:50%;background:rgba(0,0,0,.06);color:var(--tx3);font-size:24px;font-weight:800;cursor:pointer}.welfare-confirm .confirm-close:hover{background:var(--danger);color:#fff}.welfare-confirm h3{color:#f4c542;font-size:1.4rem;margin-bottom:12px}.welfare-confirm-message{color:#2ecc71;font-weight:700;font-size:1.05rem}.welfare-confirm-warning{display:block;margin-top:10px;color:#e74c3c;font-weight:700;font-size:.95rem}.welfare-confirm-buttons{display:flex;gap:12px;justify-content:center;margin-top:24px}.welfare-confirm-buttons button{padding:9px 20px;border:1.5px solid;border-radius:8px;font:700 .9rem inherit;cursor:pointer}.welfare-confirm-cancel{background:#d6f5ec;color:#087b59;border-color:#7ddab8!important}.welfare-confirm-delete{background:#fde8ea;color:var(--danger);border-color:#f5a3aa!important}@keyframes welfareConfirmPop{from{transform:translate(-50%,-48%) scale(.9);opacity:0}to{transform:translate(-50%,-50%) scale(1);opacity:1}}</style>
<div id="welfareConfirmOverlay"></div><div class="welfare-confirm" id="welfareConfirm"><button type="button" class="confirm-close" onclick="closeWelfareConfirm()">×</button><h3>⚠️ Xác Nhận Xóa</h3><div class="welfare-confirm-message" id="welfareConfirmMessage"></div><span class="welfare-confirm-warning">Không thể hoàn tác!</span><div class="welfare-confirm-buttons"><button type="button" class="welfare-confirm-cancel" onclick="closeWelfareConfirm()">✖ Hủy</button><button type="button" class="welfare-confirm-delete" id="welfareConfirmDelete">🗑 Xóa</button></div></div>
<style>.modal .box{width:min(1309px,96vw)}.welfare-item-row{grid-template-columns:224px 110px minmax(360px,1fr) 38px}.welfare-options{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px}.welfare-option-row{grid-template-columns:minmax(0,1fr) 88px 34px}.welfare-option-name span:last-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}@media(max-width:620px){.modal .box{width:1309px;max-width:none}.welfare-item-row{grid-template-columns:224px 110px minmax(360px,1fr) 38px}.welfare-options{grid-template-columns:repeat(2,minmax(0,1fr))}}</style>
<div class="picker-overlay" id="itemPicker"><div class="picker-content"><div class="picker-head"><b>CHỌN VẬT PHẨM</b><input id="itemPickerSearch" placeholder="Tìm tên hoặc ID..." oninput="filterItemPicker()"><button class="picker-close" onclick="closePicker('itemPicker')">ĐÓNG</button></div><div class="picker-scroll"><div class="picker-item-grid" id="itemPickerGrid"></div></div></div></div>
<div class="picker-overlay" id="optionPicker"><div class="picker-content option-picker"><div class="picker-head"><b style="color:var(--kame-green)">⚡ CHỌN CHỈ SỐ</b><input id="optionPickerSearch" placeholder="Tìm tên hoặc ID chỉ số..." oninput="filterOptionPicker()"><button class="picker-close" onclick="closePicker('optionPicker')">ĐÓNG</button></div><div class="picker-scroll"><div class="picker-option-grid" id="optionPickerGrid"></div></div></div></div>
<script>
const tabs=<?=json_encode($tabs,JSON_UNESCAPED_UNICODE)?>, labels=<?=json_encode($labels,JSON_UNESCAPED_UNICODE)?>, items=<?=json_encode($items,JSON_UNESCAPED_UNICODE)?>, optionTemplates=<?=json_encode($optionTemplates,JSON_UNESCAPED_UNICODE)?>, initial=<?=json_encode($initial,JSON_UNESCAPED_UNICODE)?>;let data={},active=0,editing=null,draft=[];Object.keys(initial).forEach(k=>data[k]=parse(initial[k]));function parse(s){return s?s.split(';').filter(Boolean).map(x=>{let[a,b,c='-']=x.split(',');return{id:+a,qty:+b,ops:c}}):[]}function esc(x){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function item(id){return items.find(x=>x.id===id)||{id,name:'Vật phẩm không rõ',icon:0}}function iconUrl(x){return `/icon/${x.icon||'default'}.png`}function optionHtml(ops){if(ops==='-')return 'Không cần chỉ số';return ops.split('|').map(raw=>{let p=raw.indexOf(':'),id=+(p<0?raw:raw.slice(0,p)),param=p<0?'':raw.slice(p+1),tpl=optionTemplates.find(x=>x.id===id),name=tpl?tpl.name:`Option#${id}`;name=esc(name);return '+ '+(name.includes('#')?name.replace(/#/g,`<b>${esc(param)}</b>`):name)}).join('<br>')}function render(){document.getElementById('tabs').innerHTML=tabs.map((x,i)=>`<button class="tab ${i===active?'active':''}" onclick="active=${i};render()">${i+1}. ${x}</button>`).join('');document.getElementById('title').textContent=tabs[active];let out='';labels[active].forEach((label,m)=>{let k=`${active}.${m}`, rewards=data[k]||[];out+=`<tr><td><b>${esc(label)}</b></td><td>${rewards.length?`<div class="reward-items">${rewards.map(r=>{let it=item(r.id);return `<div class="reward"><img class="icon" src="${iconUrl(it)}" onerror="this.src='/icon/default.png'"><span><strong>x${r.qty} ${esc(it.name)}</strong><small>${optionHtml(r.ops)}</small></span></div>`}).join('')}</div>`:'<i>Chưa có quà</i>'}</td><td><div class="actions"><button class="btn edit" onclick="openEditor('${k}')">Sửa</button><button class="btn delete" onclick="clearReward('${k}')">Xóa</button></div></td></tr>`});document.getElementById('rows').innerHTML=out}function selectHtml(id){return items.map(x=>`<option value="${x.id}" ${x.id===id?'selected':''}>${x.id} - ${esc(x.name)}</option>`).join('')}function renderEditor(){document.getElementById('editorRows').innerHTML=draft.map((r,i)=>`<div class="item-row"><select onchange="draft[${i}].id=+this.value">${selectHtml(r.id)}</select><input type="number" min="1" value="${r.qty}" onchange="draft[${i}].qty=Math.max(1,+this.value||1)"><input value="${esc(r.ops)}" onchange="draft[${i}].ops=this.value" placeholder="- hoặc 30:1|101:5"><button class="x" onclick="draft.splice(${i},1);renderEditor()">×</button></div>`).join('')}function openEditor(key){editing=key||`${active}.0`;draft=JSON.parse(JSON.stringify(data[editing]||[]));if(!draft.length)draft=[{id:items[0]?.id||0,qty:1,ops:'-'}];document.getElementById('modalTitle').textContent=key?'Sửa Phúc Lợi':'Tạo Phúc Lợi';renderEditor();document.getElementById('modal').classList.add('show')}function closeEditor(){document.getElementById('modal').classList.remove('show')}function addItem(){draft.push({id:items[0]?.id||0,qty:1,ops:'-'});renderEditor()}function applyEdit(){if(!draft.length)return toast('Cần ít nhất một vật phẩm');for(const x of draft)if(!/^(-|\d+:\d+(\|\d+:\d+)*)$/.test(x.ops))return toast('Chỉ số chưa đúng định dạng');data[editing]=draft;closeEditor();render()}function clearReward(k){if(confirm('Xóa toàn bộ quà của mốc này?')){data[k]=[];render()}}async function save(){for(const k in data)if(!data[k].length)return toast('Tạo lại quà cho các mốc đã xóa trước khi lưu');let f=new FormData();f.append('csrf_token','<?=htmlspecialchars($csrf,ENT_QUOTES)?>');f.append('rewards',JSON.stringify(data));let r=await fetch(location.href,{method:'POST',body:f});let j=await r.json();toast(j.message||'Đã lưu');if(!j.ok)console.error(j)}function toast(s){let e=document.getElementById('toast');e.textContent=s;e.style.display='block';setTimeout(()=>e.style.display='none',2500)}render();
</script><script>
const importantOptionIds=[0,6,7,10,11,12,13,14,30,50,77,101,103,106,156,160,210];let pickerItemIndex=null,pickerOptionIndex=null;
function optionParts(ops){if(!ops||ops==='-')return[];return ops.split('|').filter(Boolean).map(raw=>{let p=raw.indexOf(':');return{id:+raw.slice(0,p),param:raw.slice(p+1)}})}
function setOptionParts(index,parts){draft[index].ops=parts.length?parts.map(x=>`${x.id}:${Math.max(0,+x.param||0)}`).join('|'):'-'}
function renderEditor(){document.getElementById('editorRows').innerHTML=draft.map((r,i)=>{let it=item(r.id),parts=optionParts(r.ops);return `<div class="welfare-item-row"><div class="welfare-field"><label>Vật phẩm mục tiêu</label><div class="welfare-trigger" onclick="openItemPicker(${i})"><img src="${iconUrl(it)}" onerror="this.src='/icon/default.png'"><b>${esc(it.name)}</b></div></div><div class="welfare-field"><label>Số lượng</label><input class="welfare-qty" type="number" min="1" value="${r.qty}" oninput="draft[${i}].qty=Math.max(1,+this.value||1)"></div><div class="welfare-field"><label>Chỉ số</label><div class="welfare-options">${parts.map((o,j)=>{let tpl=optionTemplates.find(x=>x.id===o.id),name=tpl?tpl.name:`Option#${o.id}`;return `<div class="welfare-option-row"><div class="welfare-option-name"><span class="welfare-option-id">${o.id}</span><span>${esc(name)}</span></div><input type="number" value="${esc(o.param)}" placeholder="Giá trị" oninput="updateDraftOption(${i},${j},this.value)"><button class="x" onclick="removeDraftOption(${i},${j})">×</button></div>`}).join('')}</div><button type="button" class="welfare-add-option" onclick="openOptionPicker(${i})">+ Thêm chỉ số</button></div><button class="x" title="Xóa vật phẩm" onclick="draft.splice(${i},1);renderEditor()">×</button></div>`}).join('')}
const renderEditorBase=renderEditor;renderEditor=function(){renderEditorBase();document.querySelectorAll('.welfare-add-option').forEach((button,i)=>{let actions=document.createElement('div');actions.className='welfare-option-actions';button.parentNode.insertBefore(actions,button);actions.appendChild(button);let noOption=document.createElement('button');noOption.type='button';noOption.className='welfare-no-option'+(draft[i].ops==='-'?' active':'');noOption.textContent='Không chỉ số';noOption.onclick=()=>clearDraftOptions(i);actions.appendChild(noOption)});document.querySelectorAll('.welfare-item-row').forEach((row,i)=>{let itemDelete=row.querySelector(':scope > .x');if(itemDelete){itemDelete.onclick=null;itemDelete.addEventListener('click',()=>openWelfareConfirm('Xóa vật phẩm này khỏi mốc phúc lợi?',()=>{draft.splice(i,1);renderEditor()}))}row.querySelectorAll('.welfare-option-row .x').forEach((button,j)=>{button.onclick=null;button.addEventListener('click',()=>openWelfareConfirm('Xóa chỉ số này khỏi vật phẩm?',()=>removeDraftOption(i,j)))})})};
let welfareConfirmAction=null;function openWelfareConfirm(message,action){welfareConfirmAction=action;document.getElementById('welfareConfirmMessage').textContent=message;document.getElementById('welfareConfirmOverlay').classList.add('show');document.getElementById('welfareConfirm').classList.add('show')}function closeWelfareConfirm(){welfareConfirmAction=null;document.getElementById('welfareConfirmOverlay').classList.remove('show');document.getElementById('welfareConfirm').classList.remove('show')}document.getElementById('welfareConfirmDelete').addEventListener('click',()=>{let action=welfareConfirmAction;closeWelfareConfirm();if(action)action()});document.getElementById('welfareConfirmOverlay').addEventListener('click',closeWelfareConfirm);
function clearDraftOptions(i){draft[i].ops='-';renderEditor()}
let welfareToastTimer=null;toast=function(message,isError=false){let e=document.getElementById('toast');e.textContent=message;e.classList.remove('error','show');if(isError)e.classList.add('error');void e.offsetWidth;e.classList.add('show');clearTimeout(welfareToastTimer);welfareToastTimer=setTimeout(()=>e.classList.remove('show'),2000)};
save=async function(){for(const k in data)if(!data[k].length)return toast('Tạo lại quà cho các mốc đã xóa trước khi lưu',true);let f=new FormData();f.append('csrf_token','<?=htmlspecialchars($csrf,ENT_QUOTES)?>');f.append('rewards',JSON.stringify(data));try{let r=await fetch(location.href,{method:'POST',body:f}),j=await r.json();if(j.ok)toast('Đã Cập Nhật Quà Mới');else toast(j.message||'Cập nhật thất bại',true)}catch(e){toast('Không thể kết nối máy chủ',true)}};
function updateDraftOption(i,j,value){let parts=optionParts(draft[i].ops);if(parts[j]){parts[j].param=value;setOptionParts(i,parts)}}
function removeDraftOption(i,j){let parts=optionParts(draft[i].ops);parts.splice(j,1);setOptionParts(i,parts);renderEditor()}
function closePicker(id){document.getElementById(id).classList.remove('show')}
function openItemPicker(index){pickerItemIndex=index;let grid=document.getElementById('itemPickerGrid');grid.innerHTML=items.map((x,n)=>`<div class="picker-item" data-search="${esc((x.name+' '+x.id).toLowerCase())}" onclick="selectPickerItem(${n})"><img src="${iconUrl(x)}" loading="lazy" onerror="this.src='/icon/default.png'"><strong>${esc(x.name)}</strong><code>ID: ${x.id}</code></div>`).join('');document.getElementById('itemPickerSearch').value='';document.getElementById('itemPicker').classList.add('show');setTimeout(()=>document.getElementById('itemPickerSearch').focus(),0)}
function selectPickerItem(n){if(pickerItemIndex===null)return;draft[pickerItemIndex].id=items[n].id;closePicker('itemPicker');renderEditor()}
function filterItemPicker(){let q=document.getElementById('itemPickerSearch').value.toLowerCase().trim();document.querySelectorAll('#itemPickerGrid .picker-item').forEach(x=>x.style.display=x.dataset.search.includes(q)?'flex':'none')}
function openOptionPicker(index){pickerOptionIndex=index;let grid=document.getElementById('optionPickerGrid');grid.innerHTML=optionTemplates.map((x,n)=>`<div class="picker-option ${importantOptionIds.includes(x.id)?'important':''}" data-search="${esc((x.name+' '+x.id).toLowerCase())}" onclick="selectPickerOption(${n})"><span class="oid">${x.id}</span><span class="oname">${esc(x.name)}</span><span>›</span></div>`).join('');document.getElementById('optionPickerSearch').value='';document.getElementById('optionPicker').classList.add('show');setTimeout(()=>document.getElementById('optionPickerSearch').focus(),0)}
function selectPickerOption(n){if(pickerOptionIndex===null)return;let parts=optionParts(draft[pickerOptionIndex].ops),chosen=optionTemplates[n];parts.push({id:chosen.id,param:0});setOptionParts(pickerOptionIndex,parts);closePicker('optionPicker');renderEditor()}
function filterOptionPicker(){let q=document.getElementById('optionPickerSearch').value.toLowerCase().trim();document.querySelectorAll('#optionPickerGrid .picker-option').forEach(x=>x.style.display=x.dataset.search.includes(q)?'flex':'none')}
addItem=function(){if(draft.length>=6)return toast('Mỗi mốc chỉ được tối đa 6 vật phẩm');draft.push({id:items[0]?.id||0,qty:1,ops:'-'});renderEditor();openItemPicker(draft.length-1)};
render=function(){document.getElementById('tabs').innerHTML=tabs.map((x,i)=>`<button class="tab ${i===active?'active':''}" onclick="active=${i};render()">${i+1}. ${x}</button>`).join('');document.getElementById('title').textContent=tabs[active];let out='';labels[active].forEach((label,m)=>{let k=`${active}.${m}`,rewards=data[k]||[];out+=`<tr><td><b>${esc(label)}</b></td><td>${rewards.length?`<div class="reward-items">${rewards.map(r=>{let it=item(r.id);return `<div class="reward"><img class="icon" src="${iconUrl(it)}" onerror="this.src='/icon/default.png'"><div class="item-name">${esc(it.name)} <span class="item-count">x${r.qty}</span></div><small>${optionHtml(r.ops)}</small></div>`}).join('')}</div>`:'<i>Chưa có quà</i>'}</td><td><div class="actions"><button class="btn edit" onclick="openEditor('${k}')">✎ Sửa</button><button class="btn delete" onclick="clearReward('${k}')">▣ Xóa</button></div></td></tr>`});document.getElementById('rows').innerHTML=out};render();
(function(){var PAGE_W=1500,FILL=.98,scaler=document.getElementById('scaler');function applyScale(){var vw=window.innerWidth,avail=vw*FILL,ratio=avail/PAGE_W,left=(vw-avail)/2;document.documentElement.style.setProperty('--page-scale',ratio);scaler.style.width=PAGE_W+'px';scaler.style.transform='scale('+ratio+')';scaler.style.transformOrigin='top left';scaler.style.marginLeft=left+'px';document.body.style.minHeight=(scaler.offsetHeight*ratio)+'px'}applyScale();window.addEventListener('resize',applyScale)})();
const applyEditOnPage=applyEdit;applyEdit=function(){if(draft.length>6)return toast('Mỗi mốc chỉ được tối đa 6 vật phẩm');applyEditOnPage();if(!document.getElementById('modal').classList.contains('show'))save()};
const welfareHeader=document.querySelector('.tx-box');if(welfareHeader){welfareHeader.onclick=null;welfareHeader.style.cursor='default';welfareHeader.innerHTML=`<svg class="tx-ic" viewBox="0 0 24 24" width="16" height="16" fill="none" aria-hidden="true"><path d="M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1 3-6z" stroke="white" stroke-width="1.6" stroke-linejoin="round"/></svg><span>Tạo Phúc Lợi: <span style="font-family:'JetBrains Mono',monospace;font-size:.95em">15</span></span>`}
document.querySelectorAll('.actions .delete').forEach(x=>x.remove());
const panelButton=document.querySelector('.tr2 .bblue');if(panelButton)panelButton.innerHTML=`<svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 10.5L12 3L21 10.5V20A1 1 0 0 1 20 21H15V14H9V21H4A1 1 0 0 1 3 20V10.5Z" stroke="white" stroke-width="2" stroke-linejoin="round"/></svg><span>Panel</span>`;
const refreshButton=document.querySelector('.tr2 .bteal');if(refreshButton)refreshButton.innerHTML=`<svg width="15" height="15" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M20 12A8 8 0 1 1 17.3 6M20 4V12H12" stroke="white" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Làm Mới</span>`;
let panelModeEnabled=<?=json_encode($panelEnabled)?>;if(refreshButton){const modeButton=document.createElement('button');modeButton.type='button';modeButton.className='btn panel-mode-button';modeButton.style.background=panelModeEnabled?'linear-gradient(135deg,#16a34a,var(--kame-green))':'linear-gradient(135deg,#f59e0b,#d97706)';modeButton.style.color='#fff';modeButton.innerHTML=`<span>${panelModeEnabled?'✓ Đang Bật Chế Độ Panel':'Bật Chế Độ Panel'}</span>`;modeButton.onclick=togglePanelMode;refreshButton.insertAdjacentElement('afterend',modeButton)}
async function togglePanelMode(){let f=new FormData();f.append('csrf_token','<?=htmlspecialchars($csrf,ENT_QUOTES)?>');f.append('action','toggle_panel');f.append('enabled',panelModeEnabled?'0':'1');try{let r=await fetch(location.href,{method:'POST',body:f}),j=await r.json();if(!j.ok)return toast('Không thể đổi chế độ Panel',true);panelModeEnabled=!!j.enabled;toast(panelModeEnabled?'Đã Bật Chế Độ Panel':'Đã Tắt Chế Độ Panel');setTimeout(()=>location.reload(),700)}catch(e){toast('Không thể kết nối máy chủ',true)}}
</script></div><?php require __DIR__ . '/guide_widget.php'; admin_foot(); ?>
